#!/usr/bin/env node

const { performance } = require('perf_hooks');
const https = require('https');
const { magenta, bold, yellow, green, blue } = require('./chalk.js');
const stats = require('./stats.js');

const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36';

// Keep connections alive to stop Cloudflare from throwing 429 Too Many Requests
const keepAliveAgent = new https.Agent({ keepAlive: true, maxSockets: 10 });
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function get(hostname, path) {
  return new Promise((resolve, reject) => {
    const req = https.request(
      {
        hostname,
        path,
        method: 'GET',
        agent: keepAliveAgent,
        headers: {
          Referer: `https://${hostname}/`,
          'User-Agent': USER_AGENT,
        },
      },
      (res) => {
        const body = [];
        res.on('data', (chunk) => {
          body.push(chunk);
        });
        res.on('end', () => {
          try {
            resolve(Buffer.concat(body).toString());
          } catch (e) {
            reject(e);
          }
        });
        req.on('error', (err) => {
          reject(err);
        });
      }
    );

    req.end();
  });
}

async function fetchServerLocationData() {
  const res = JSON.parse(await get('speed.cloudflare.com', '/locations'));

  return res.reduce((data, { iata, city }) => {
    // Bypass prettier "no-assign-param" rules
    const data1 = data;

    data1[iata] = city;
    return data1;
  }, {});
}

function fetchCfCdnCgiTrace() {
  const parseCfCdnCgiTrace = (text) =>
    text
      .split('\n')
      .map((i) => {
        const j = i.split('=');

        return [j[0], j[1]];
      })
      .reduce((data, [k, v]) => {
        if (v === undefined) return data;

        // Bypass prettier "no-assign-param" rules
        const data1 = data;
        // Object.fromEntries is only supported by Node.js 12 or newer
        data1[k] = v;

        return data1;
      }, {});

  return get('speed.cloudflare.com', '/cdn-cgi/trace').then(parseCfCdnCgiTrace);
}

function request(options, data = '') {
  let started;
  let ttfb;
  let ended;

  options.agent = keepAliveAgent;
  options.headers = options.headers || {};
  options.headers['User-Agent'] = options.headers['User-Agent'] || USER_AGENT;

  return new Promise((resolve, reject) => {
    started = performance.now();
    const req = https.request(options, (res) => {
      // Reject blocked requests; don't calculate fake million-Mbps speeds
      if (res.statusCode >= 400) {
        req.destroy();
        return reject(new Error(`Server returned status ${res.statusCode}`));
      }

      res.once('data', () => {
        if (!ttfb) ttfb = performance.now();
      });
      res.on('data', () => {});
      res.on('end', () => {
        ended = performance.now();
        if (!ttfb) ttfb = ended;

        // Extract the duration safely, as Cloudflare sometimes shifts the header format
        let serverDuration = 0;
        const stHeader = res.headers['server-timing'];
        if (stHeader) {
          const match = stHeader.match(/dur=([\d.]+)/);
          if (match) serverDuration = parseFloat(match[1]);
        }

        resolve([
          started,
          0, // dnsLookup (unused now)
          0, // tcpHandshake (unused now)
          0, // sslHandshake (unused now)
          ttfb,
          ended,
          serverDuration,
        ]);
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(data);
    req.end();
  });
}

function download(bytes) {
  const options = {
    hostname: 'speed.cloudflare.com',
    path: `/__down?bytes=${bytes}`,
    method: 'GET',
  };

  return request(options);
}

function upload(bytes) {
  const data = '0'.repeat(bytes);
  const options = {
    hostname: 'speed.cloudflare.com',
    path: '/__up',
    method: 'POST',
    headers: {
      'Content-Length': Buffer.byteLength(data),
    },
  };

  return request(options, data);
}

function measureSpeed(bytes, duration) {
  // Prevent division by zero if transfer time is super fast
  const safeDuration = Math.max(duration, 1);
  return (bytes * 8) / (safeDuration / 1000) / 1e6;
}

async function measureLatency() {
  const measurements = [];

  for (let i = 0; i < 20; i += 1) {
    try {
      const response = await download(1000);
      // TTFB - Server processing time
      measurements.push(response[4] - response[0] - response[6]);
    } catch (error) {
      // Silently ignore dropouts
    }
    await sleep(25);
  }

  if (measurements.length === 0) return [0, 0, 0, 0, 0];

  return [
    Math.min(...measurements),
    Math.max(...measurements),
    stats.average(measurements),
    stats.median(measurements),
    stats.jitter(measurements),
  ];
}

async function measureDownload(bytes, iterations) {
  const measurements = [];

  for (let i = 0; i < iterations; i += 1) {
    let attempts = 0;
    let success = false;

    // Cap retries to prevent the script from exceeding the 2-minute Nagios timeout
    while (!success && attempts < 2) {
      try {
        const response = await download(bytes);
        const transferTime = response[5] - response[4];
        measurements.push(measureSpeed(bytes, transferTime));
        success = true;
      } catch (error) {
        attempts += 1;
        if (error.message.includes('429') || error.message.includes('403')) {
          // Back off for 1.5s the CF WAF kicks in, then try once more
          await sleep(1500);
        } else {
          break;
        }
      }
    }
    await sleep(150);
  }

  return measurements;
}

async function measureUpload(bytes, iterations) {
  const measurements = [];

  for (let i = 0; i < iterations; i += 1) {
    let attempts = 0;
    let success = false;

    while (!success && attempts < 2) {
      try {
        const response = await upload(bytes);
        const transferTime = response[5] - response[0];
        measurements.push(measureSpeed(bytes, transferTime));
        success = true;
      } catch (error) {
        attempts += 1;
        if (error.message.includes('429') || error.message.includes('403')) {
          await sleep(1500);
        } else {
          break;
        }
      }
    }
    await sleep(150);
  }

  return measurements;
}

function logInfo(text, data) {
  console.log(bold(' '.repeat(15 - text.length), `${text}:`, blue(data)));
}

function logLatency(data) {
  console.log(bold('         Latency:', magenta(`${data[3].toFixed(2)} ms`)));
  console.log(bold('          Jitter:', magenta(`${data[4].toFixed(2)} ms`)));
}

function logSpeedTestResult(size, test) {
  // Always return a float so the programmatic parser in nems-scripts doesn't break
  const speed = test.length > 0 ? stats.median(test).toFixed(2) : '0.00';
  console.log(
    bold(' '.repeat(9 - size.length), size, 'speed:', yellow(`${speed} Mbps`))
  );
}

function logDownloadSpeed(tests) {
  const speed = tests.length > 0 ? stats.quartile(tests, 0.9).toFixed(2) : '0.00';
  console.log(bold('  Download speed:', green(speed, 'Mbps')));
}

function logUploadSpeed(tests) {
  const speed = tests.length > 0 ? stats.quartile(tests, 0.9).toFixed(2) : '0.00';
  console.log(bold('    Upload speed:', green(speed, 'Mbps')));
}

async function speedTest() {
  try {
    const [ping, serverLocationData, { ip, loc, colo }] = await Promise.all([
      measureLatency(),
      fetchServerLocationData(),
      fetchCfCdnCgiTrace(),
    ]);

    const city = serverLocationData[colo] || 'Unknown';
    logInfo('Server location', `${city} (${colo})`);
    logInfo('Your IP', `${ip} (${loc})`);

    logLatency(ping);

    // Run the tests
    // Reduced iterations to keep the run safely under limits
    const testDown1 = await measureDownload(101000, 5);
    logSpeedTestResult('100kB', testDown1);

    const testDown2 = await measureDownload(1001000, 4);
    logSpeedTestResult('1MB', testDown2);

    const testDown3 = await measureDownload(10001000, 3);
    logSpeedTestResult('10MB', testDown3);

    const testDown4 = await measureDownload(25001000, 2);
    logSpeedTestResult('25MB', testDown4);

    // Give the WAF a breather before attempting the massive 100MB chunk
    await sleep(1500);

    const testDown5 = await measureDownload(100001000, 1);
    logSpeedTestResult('100MB', testDown5);

    const downloadTests = [
      ...testDown1,
      ...testDown2,
      ...testDown3,
      ...testDown4,
      ...testDown5,
    ];
    logDownloadSpeed(downloadTests);

    await sleep(1000); 

    const testUp1 = await measureUpload(11000, 5);
    const testUp2 = await measureUpload(101000, 5);
    const testUp3 = await measureUpload(1001000, 4);
    const uploadTests = [...testUp1, ...testUp2, ...testUp3];
    logUploadSpeed(uploadTests);
  } catch (error) {
    console.error('Speed test failed:', error);
  } finally {
    keepAliveAgent.destroy();
  }
}

speedTest();
